module radix2_div (
    input wire clk,
    input wire rst,
    input wire [7:0] dividend,
    input wire [7:0] divisor,
    input wire sign,
    input wire opn_valid,
    output reg res_valid,
    input wire res_ready,
    output wire [15:0] result
);

reg [15:0] SR;
reg [3:0] cnt;
reg [3:0] start_cnt;
reg [7:0] NEG_DIVISOR;

always @(posedge clk) begin
    if (rst) begin
        SR <= 16'b0;
        cnt <= 4'b0;
        start_cnt <= 4'b0;
        NEG_DIVISOR <= 8'b0;
        res_valid <= 1'b0;
    end else if (opn_valid && ~res_valid) begin
        if (sign) begin
            SR[15:8] <= {dividend[7], dividend};
            SR[7:0] <= 8'b0;
        end else begin
            SR[15:8] <= {dividend[7], dividend};
            SR[7:0] <= 8'b0;
        end
        NEG_DIVISOR <= -divisor;
        cnt <= 4'b1;
        start_cnt <= 4'b1;
        res_valid <= 1'b1;
    end else if (start_cnt && !res_ready) begin
        if (cnt == 4'd8) begin
            cnt <= 4'b0;
            start_cnt <= 4'b0;
            SR[15:8] <= SR[7:0];
            SR[7:0] <= 8'b0;
        end else begin
            if (SR >= NEG_DIVISOR) begin
                SR = SR - NEG_DIVISOR;
            end
            SR = {SR[14:0], 1'b0};
            cnt <= cnt + 1'b1;
        end
    end else begin
        res_valid <= 1'b0;
    end
end

assign result = SR;

endmodule
